insert into public.routines (id, kind, title, content) values ('board-demo', 'board', 'Pizarrón — Tren superior', '{"focus":"Tren superior","blocks":[{"name":"Zona media","scheme":"×3","note":"Circuito, con el mínimo descanso posible.","items":[{"exercises":[{"ex":"abdominales","prescription":"20"}]},{"exercises":[{"ex":"superman","prescription":"20"}]},{"exercises":[{"ex":"canoa","prescription":"30”"}]}]},{"name":"Rutina principal (5 ejercicios)","scheme":"×3","note":"Descanso 1–1:30 min entre rondas.","items":[{"exercises":[{"ex":"push-ups","prescription":"10-12"},{"ex":"chin-ups","prescription":"20"}]},{"exercises":[{"ex":"fondos","prescription":"8-10"},{"ex":"ext-triceps","prescription":"12"}]},{"exercises":[{"ex":"pike-push-up","prescription":"8-12"},{"ex":"australianas","prescription":"15"}]},{"exercises":[{"ex":"pseudo-push-up","prescription":"10"},{"ex":"pull-ups","prescription":"6-8"}]},{"exercises":[{"ex":"l-sit","prescription":"15”"},{"ex":"bicycle-abs","prescription":"30”"}]}]},{"name":"Complemento (tren inferior)","scheme":"×3","note":"Trabajo opuesto al día. Descanso corto.","items":[{"exercises":[{"ex":"sentadilla","prescription":"20"}]},{"exercises":[{"ex":"estocada","prescription":"12 x pierna"}]},{"exercises":[{"ex":"pantorrilla","prescription":"20"}]}]}]}'::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.routines (id, kind, title, content) values ('board-piernas', 'board', 'Pizarrón — Tren inferior', '{"focus":"Tren inferior (piernas)","blocks":[{"name":"Zona media","scheme":"×3","note":"Circuito, con el mínimo descanso posible.","items":[{"exercises":[{"ex":"abdominales","prescription":"20"}]},{"exercises":[{"ex":"lev-pierna","prescription":"15"}]},{"exercises":[{"ex":"plancha-lateral","prescription":"30” x lado"}]}]},{"name":"Rutina principal (5 ejercicios)","scheme":"×3","note":"Descanso 1–1:30 min entre rondas.","items":[{"exercises":[{"ex":"sentadilla","prescription":"15-20"},{"ex":"pantorrilla","prescription":"20"}]},{"exercises":[{"ex":"estocada","prescription":"12 x pierna"},{"ex":"mountain-climber","prescription":"40”"}]},{"exercises":[{"ex":"shrimp","prescription":"6-8 x pierna (asistida)"},{"ex":"sentadilla","prescription":"30” isométrico"}]},{"exercises":[{"ex":"pistol","prescription":"5 x pierna (asistida)"},{"ex":"nordica","prescription":"5-8"}]},{"exercises":[{"ex":"estocada","prescription":"12 con salto x pierna"},{"ex":"plancha-lateral","prescription":"20”"}]}]},{"name":"Complemento (tren superior)","scheme":"×3","note":"Trabajo opuesto al día. Descanso corto.","items":[{"exercises":[{"ex":"push-ups","prescription":"12"}]},{"exercises":[{"ex":"australianas","prescription":"12"}]},{"exercises":[{"ex":"fondos","prescription":"8-10"}]}]}]}'::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.routines (id, kind, title, content) values ('board-full', 'board', 'Pizarrón — Cuerpo completo', '{"focus":"Cuerpo completo (full body)","blocks":[{"name":"Zona media","scheme":"×3","note":"Circuito, con el mínimo descanso posible.","items":[{"exercises":[{"ex":"bicycle-abs","prescription":"30”"}]},{"exercises":[{"ex":"superman","prescription":"20"}]},{"exercises":[{"ex":"canoa","prescription":"30”"}]}]},{"name":"Rutina principal (5 ejercicios)","scheme":"×3","note":"Descanso 1–1:30 min entre rondas.","items":[{"exercises":[{"ex":"push-ups","prescription":"10-12"},{"ex":"sentadilla","prescription":"20"}]},{"exercises":[{"ex":"australianas","prescription":"12-15"},{"ex":"estocada","prescription":"12 x pierna"}]},{"exercises":[{"ex":"pike-push-up","prescription":"8-10"},{"ex":"lev-pierna","prescription":"12"}]},{"exercises":[{"ex":"chin-ups","prescription":"6-8"},{"ex":"fondos","prescription":"8-10"}]},{"exercises":[{"ex":"mountain-climber","prescription":"40”"},{"ex":"plancha-lateral","prescription":"20” x lado"}]}]},{"name":"Complemento (movilidad y core)","scheme":"×3","note":"Descanso corto.","items":[{"exercises":[{"ex":"pantorrilla","prescription":"20"}]},{"exercises":[{"ex":"abdominales","prescription":"20"}]},{"exercises":[{"ex":"superman","prescription":"15"}]}]}]}'::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.routines (id, kind, title, content) values ('board-empuje', 'board', 'Pizarrón — Empuje (push)', '{"focus":"Empuje (pecho, hombro, tríceps)","blocks":[{"name":"Zona media","scheme":"×3","note":"Circuito, con el mínimo descanso posible.","items":[{"exercises":[{"ex":"abdominales","prescription":"20"}]},{"exercises":[{"ex":"l-sit","prescription":"15”"}]},{"exercises":[{"ex":"plancha-lateral","prescription":"30” x lado"}]}]},{"name":"Rutina principal (5 ejercicios)","scheme":"×3","note":"Descanso 1–1:30 min entre rondas.","items":[{"exercises":[{"ex":"push-ups","prescription":"10-15"},{"ex":"fondos","prescription":"8-10"}]},{"exercises":[{"ex":"pike-push-up","prescription":"8-12"},{"ex":"ext-triceps","prescription":"12"}]},{"exercises":[{"ex":"pseudo-push-up","prescription":"10"},{"ex":"bar-dips","prescription":"8-10"}]},{"exercises":[{"ex":"push-ups","prescription":"máx (diamante)"},{"ex":"mountain-climber","prescription":"40”"}]},{"exercises":[{"ex":"pike-push-up","prescription":"8” en pared (progresión HSPU)"},{"ex":"abdominales","prescription":"20"}]}]},{"name":"Complemento (tracción y pierna)","scheme":"×3","note":"Trabajo opuesto al día. Descanso corto.","items":[{"exercises":[{"ex":"australianas","prescription":"15"}]},{"exercises":[{"ex":"sentadilla","prescription":"20"}]},{"exercises":[{"ex":"pantorrilla","prescription":"20"}]}]}]}'::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.routines (id, kind, title, content) values ('board-traccion', 'board', 'Pizarrón — Tracción (espalda y bíceps)', '{"focus":"Tracción (espalda, dorsal, bíceps)","blocks":[{"name":"Zona media","scheme":"×3","note":"Circuito, con el mínimo descanso posible.","items":[{"exercises":[{"ex":"superman","prescription":"20"}]},{"exercises":[{"ex":"canoa","prescription":"30”"}]},{"exercises":[{"ex":"lev-pierna","prescription":"12"}]}]},{"name":"Rutina principal (5 ejercicios)","scheme":"×3","note":"Descanso 1–1:30 min entre rondas.","items":[{"exercises":[{"ex":"chin-ups","prescription":"6-8"},{"ex":"australianas","prescription":"12-15"}]},{"exercises":[{"ex":"pull-ups","prescription":"5-8"},{"ex":"superman","prescription":"20"}]},{"exercises":[{"ex":"australianas","prescription":"máx (supinado)"},{"ex":"canoa","prescription":"30”"}]},{"exercises":[{"ex":"chin-ups","prescription":"negativas 5 x 5”"},{"ex":"lev-pierna","prescription":"10"}]},{"exercises":[{"ex":"pull-ups","prescription":"máx"},{"ex":"plancha-lateral","prescription":"20”"}]}]},{"name":"Complemento (empuje y pierna)","scheme":"×3","note":"Trabajo opuesto al día. Descanso corto.","items":[{"exercises":[{"ex":"push-ups","prescription":"12"}]},{"exercises":[{"ex":"sentadilla","prescription":"20"}]},{"exercises":[{"ex":"fondos","prescription":"8"}]}]}]}'::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
insert into public.routines (id, kind, title, content) values ('plan-cerve-3dias', 'plan', 'Programa 3 días — Vertical / Piernas / Espalda', '{"subtitle":"Semanas 1 a 5 · se repite cada semana (sobrecarga progresiva)","objetivos":["Lograr una vertical sólida y aumentar fuerza","Ganar resistencia y acondicionamiento en los básicos","Iniciar en back lever","Fortalecer piernas y ganar músculo"],"days":[{"title":"Día 1 — Vertical y tren superior","blocks":[{"name":"Entrada en calor","note":"Movimientos articulares + circuito de abdomen. 2 sets, sin descansar más de 1 min.","items":[{"exercises":[{"ex":"push-ups","prescription":"5 con aplauso"}]},{"exercises":[{"ex":"lev-pierna","prescription":"10 en barra"}]},{"exercises":[{"ex":"lev-pierna","prescription":"10 en suelo"}]},{"exercises":[{"ex":"bicycle-abs","prescription":"30”"}]},{"exercises":[{"ex":"back-lever","prescription":"Máx (tuck)"}]}]},{"name":"Entrenamiento principal","items":[{"scheme":"×3","rest":"1–1:30 min","exercises":[{"ex":"tuck-planche","prescription":"5”"},{"ex":"l-sit","prescription":"5”"},{"ex":"vertical","prescription":"15”"}]},{"scheme":"×3","rest":"1–1:30 min","exercises":[{"ex":"muscle-up","prescription":"4-7"},{"ex":"bar-dips","prescription":"10"},{"ex":"l-sit","prescription":"12-20” en paralelas"}]},{"scheme":"×3","rest":"1–1:30 min","exercises":[{"ex":"pike-push-up","prescription":"7-14 elevadas"},{"ex":"mountain-climber","prescription":"40”"}]},{"scheme":"×3","rest":"1–1:30 min","exercises":[{"ex":"fondos","prescription":"6-16 (+12 kg)"},{"ex":"ext-triceps","prescription":"6-12 en plancha"}]},{"scheme":"×3","rest":"1–1:30 min","exercises":[{"ex":"australianas","prescription":"12-20 elevadas"},{"ex":"dragon-flag","prescription":"10” hold a 45°"}]}]}]},{"title":"Día 2 — Full piernas","blocks":[{"name":"Entrada en calor","note":"Movimientos articulares + circuito de abdomen. 3 sets, sin descansar más de 1 min.","items":[{"exercises":[{"ex":"sentadilla","prescription":"12 bisagras"}]},{"exercises":[{"ex":"plancha-lateral","prescription":"12 x lado + 12” hold"}]},{"exercises":[{"ex":"mountain-climber","prescription":"30"}]}]},{"name":"Entrenamiento principal","note":"3–4 sets con descanso de 2–3 min por ronda.","items":[{"exercises":[{"ex":"pistol","prescription":"8-12 x pierna"}]},{"exercises":[{"ex":"sentadilla","prescription":"6-12 ext. cuádriceps + 35” isométrico"}]},{"exercises":[{"ex":"shrimp","prescription":"8-12 x pierna"},{"ex":"estocada","prescription":"10 c/ salto x pierna"}]},{"exercises":[{"ex":"estocada","prescription":"20 pasos con carga"}]},{"exercises":[{"ex":"nordica","prescription":"5-10"}]},{"exercises":[{"ex":"pantorrilla","prescription":"30-30-30"}]}]}]},{"title":"Día 3 — Tren superior, espalda y bíceps","blocks":[{"name":"Entrada en calor","note":"Movimientos articulares + circuito de abdomen. 2 sets, sin descansar más de 1 min.","items":[{"exercises":[{"ex":"plancha-lateral","prescription":"12 brazo extendido"}]},{"exercises":[{"ex":"canoa","prescription":"30”"}]},{"exercises":[{"ex":"back-lever","prescription":"Máx (tuck)"}]}]},{"name":"Entrenamiento principal","items":[{"scheme":"×3","rest":"1–1:30 min","exercises":[{"ex":"vertical","prescription":"Máx"},{"ex":"l-sit","prescription":"3”"},{"ex":"pseudo-push-up","prescription":"8-15"}]},{"scheme":"×3","rest":"1–1:30 min","exercises":[{"ex":"pull-ups","prescription":"6-8 (+6 kg)"},{"ex":"back-lever","prescription":"5” hold"}]},{"scheme":"×3","rest":"1–1:30 min","exercises":[{"ex":"push-ups","prescription":"12-20 espartanas"}]},{"scheme":"×3","rest":"1–1:30 min","exercises":[{"ex":"l-sit","prescription":"4-6 pull up en tuck"}]},{"scheme":"×3","rest":"1–1:30 min","exercises":[{"ex":"fondos","prescription":"8-16"},{"ex":"front-lever","prescription":"5 raises + 10” tuck"}]}]}]}]}'::jsonb) on conflict (id) do update set title = excluded.title, content = excluded.content;
